<?php/** * 微信小程序服务 */namespace app\api\service\public;use app\api\service\CommService;use app\common\model\business\MallCustomer;use app\common\model\system\SystemConfig;use EasyWeChat\Factory;use Exception;use support\exception\BusinessException;use support\think\Db;class AppletService extends CommService{    protected $app = [];    protected $app_id = '';    protected $is_debug = false;    protected $category = 'applet';    protected $access_path = '';    protected $storage_path = '';    public function __construct($param)    {        parent::_initialize($param);//        $this->access_path = $_SERVER['REQUEST_SCHEME'] . '://' . $_SERVER['HTTP_HOST'] . '/qrcode/applet/';//        $this->storage_path = $_SERVER['DOCUMENT_ROOT'] . '/qrcode/applet';//        if (!file_exists($this->storage_path)) {//            mkdir($this->storage_path);//        }        $where['group'] = 'applet';        $app_config = SystemConfig::where($where)->column('value', 'name');//dd($app_config);        if (empty($app_config)) {            return throwError('app_id错误');        }        if (empty($app_config['appid']) || empty($app_config['appsecret'])) {            return throwError('微信小程序配置不全');        }        $this->app_id = $app_config['appid'];        $config = [            'app_id' => $app_config['appid'],            'secret' => $app_config['appsecret'],            // 下面为可选项            // 指定 API 调用返回结果的类型：array(default)/collection/object/raw/自定义类名            'response_type' => 'array',            'log' => [                'level' => 'debug',                'file' => __DIR__ . '/wechat.log',            ],        ];        $this->app = Factory::miniProgram($config);    }    public function doLogin($login_code)    {        Db::startTrans();        try {            $info = $this->getAppletInfo($login_code);            $MallCustomer = new MallCustomer();            $user_info = $MallCustomer->findUser(['unionid' => $info['user']['unionid']]);            $this->data['user_info'] = $MallCustomer->doLogin($user_info, $info['user'], true, $info['user']['app_id'], $info['recommend_id'], $this->category);            Db::commit();        } catch (Exception $e) {            Db::rollback();            throw new BusinessException($e->getMessage(), 401);        }        return $this->data;    }    public function getAppletInfo($login_code)    {        if ($this->is_debug) {            $openid = '1234568790';            $unionid = '1234568790';        } else {            $wechat_user_info = $this->app->auth->session($login_code);            if (isset($wechat_user_info['errcode'])) {                return throwError($wechat_user_info['errmsg'], $wechat_user_info['errcode']);            }            $openid = $wechat_user_info['openid'];            $unionid = $wechat_user_info['unionid'] ?? $wechat_user_info['openid'];        }        $user['openid'] = $openid;        $user['unionid'] = $unionid;        $user['app_id'] = $this->app_id;//      $user['channel'] = $this->param['channel'] ?? '';        $recommend_id = 0;//        if (!empty($this->param['sign_id'])) {//            $sign_info = $table->where('id', $this->param['sign_id'])->find();//            if ($sign_info) {//                $recommend_id = $sign_info['customer_id'];//            }//        }        return ['user' => $user, 'recommend_id' => $recommend_id];    }    public function getUserPhone($phone_code, $customer_id)    {        try {            $phone = $this->getAppletPhone($phone_code);            $user_info = MallCustomer::where('customer_id', $customer_id)->find();            $user_info->phone_number = $phone['phone_number'];            $user_info->country_code = $phone['country_code'];            $user_info->save();        } catch (Exception $e) {            throw new BusinessException($e->getMessage(), 401);        }        return $this->data;    }    public function getAppletPhone($phone_code)    {        if ($this->is_debug) {            $phone_number = '15319751011';            $country_code = '86';        } else {            $info = $this->app->phone_number->getUserPhoneNumber($phone_code);            if ($info['errcode']) {                return throwError($info['errmsg'], $info['errcode']);            }            $phone_number = $info['phone_info']['phoneNumber'];            $country_code = $info['phone_info']['countryCode'];        }        return ['phone_number' => $phone_number, 'country_code' => $country_code];    }    public function createLessAppCode()    {        $qr_filename = md5($this->param['path']) . '.png';        if (file_exists($this->storage_path . '/' . $qr_filename)) {            $this->data['qr_url'] = $this->access_path . $qr_filename;            return $this->data;        }        $this->data['qr_url'] = $this->saveQrFile($this->app->app_code->get($this->param['path']), $qr_filename);        return $this->data;    }    protected function saveQrFile($response, $qr_filename)    {        if ($response instanceof StreamResponse) {            $filename = $response->saveAs($this->storage_path, $qr_filename);            return $this->access_path . $filename;        }        return '';    }    public function createUnlimitAppCode()    {        $qr_filename = md5($this->param['scene_value']) . '.png';        if (file_exists($this->storage_path . '/' . $qr_filename)) {            $this->data['qr_url'] = $this->access_path . $qr_filename;            return $this->data;        }        $optional['width'] = 600;        if (!empty($this->param['page'])) {            $optional['page'] = $this->param['page'];        }        $this->data['qr_url'] = $this->saveQrFile($this->app->app_code->getUnlimit($this->param['scene_value'], $optional), $qr_filename);        return $this->data;    }    public function sendMessage($touser, $template_id, $page, $form_id, $data)    {        $send_body = $this->getMessageTemplate($touser, $template_id, $page, $form_id, $data);        $send_res = $this->app->template_message->send($send_body);        if ($send_res['errcode'] != 200) {            throw new BusinessException($send_res['errmsg'], $send_res['errcode']);        }        return $this->data;    }    public function getMessageTemplate($touser, $template_id, $page, $form_id, $data)    {        $patterns = array(            '/{touser}/',            '/{page}/',            '/{form_id}/',        );        $replacements = array(            $touser,            $page,            $form_id,        );        $template = config('applet_template.' . $template_id);        //方法说明：preg_replace($pattern, $replacement, $subject, $limit, $count)  搜索subject中匹配pattern的部分， 以replacement进行替换。        $send_body = preg_replace($patterns, $replacements, $template);        $send_body = array_merge($send_body, ['data' => $data]);        return $send_body;    }}